return {
      postCommit: false,
      gitattributes: false,
      driverConfig: false,
      memoryDriverConfig: false,
    };

return {
    postCommit,
    gitattributes,
    driverConfig: driverConfigured(root, 'merge.kcrib.driver'),
    memoryDriverConfig: driverConfigured(root, `merge.${MEMORY_DRIVER}.driver`),
  };

writeFileSync(
    postCommitPath,
    spliceManaged(existing, hookBlock, MANAGED_BEGIN, MANAGED_END, !existing.length),
    { mode: 0o755 },
  );

const attrBlock = [
    GITATTR_BEGIN,
    '.crib/**/*.jsonl merge=kcrib',
    '.crib/memory/team/**/*.jsonl merge=kcrib-memory',
    GITATTR_END,
  ].join('\n');

writeFileSync(
    gitattributesPath,
    spliceManaged(attrsExisting, attrBlock, GITATTR_BEGIN, GITATTR_END, false),
  );

return {
        warnings: [
          ...result.errors.map((e) => `memory merge rejected malformed line: ${e}`),
          ...result.conflictIds.map((id) => `memory hard conflict: id ${id} differs in content`),
          ...result.warnings,
        ],
        conflicts: true,
      };

const rel = execFileSync('git', ['-C', root, 'rev-parse', '--git-dir'], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
  }).trim();

const cfg = execFileSync('git', ['-C', root, 'config', section], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();

const owner = [...counts.entries()].sort(
      (a, b) => b[1] - a[1] || a[0].localeCompare(b[0]),
    )[0]?.[0];

const topSymbols = moduleSymbols
      .map((s) => ({
        id: s.id,
        ...(s.name ? { name: s.name } : {}),
        ...(s.qualifiedName ? { qualifiedName: s.qualifiedName } : {}),
        ...(s.file ? { file: s.file } : {}),
        importance: importance.get(s.id)?.importance ?? 0,
        ...(s.stereotype ? { stereotype: s.stereotype } : {}),
        test: isTestPath(s.file),
      }))
      .sort((a, b) => {
        if (a.test !== b.test) return a.test ? 1 : -1;
        if (b.importance !== a.importance) return b.importance - a.importance;
        return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
      })
      .slice(0, topN)
      .map(({ test: _test, ...rest }) => rest);

const coverage = {
      fresh,
      pending: Math.max(0, totalTargets - fresh),
      pct: totalTargets > 0 ? Math.round((fresh / totalTargets) * 100) : 0,
    };

return buckets.map((b) => ({
    pathPrefix: b.prefix,
    name: b.prefix.split('/').pop() || b.prefix,
  }));

return {
    sectionId: readme.id,
    ...(readme.heading ? { heading: readme.heading } : {}),
    file: readme.file,
  };

out.push({
      start: blockStart,
      end: lines.length,
      text: blockParts.filter((p) => p.length > 0).join('\n'),
    });

const adj: Map<number, number>[] = Array.from(
    { length: superN },
    () => new Map<number, number>(),
  );

